pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 dummy, address accessControl) public {
        vm.assume(accessControl != address(0) && accessControl != address(this));
        // Pre-deploy a minimal access control stub (must implement checkAccess returning true)
        // We use a simple contract that always returns true for access control.
        AccessReturnTrueStub stub = new AccessReturnTrueStub();
        vm.assume(address(stub) != address(0));
        // We allow the fuzzer to vary the accessControl argument, but we need a contract address that implements IAccessControl.
        // For the property, we can just use the stub address.
        address actualControl = address(stub);

        // First initialization: must succeed
        vm.prank(actualControl);
        bool firstOk;
        try c.initialize(actualControl) { firstOk = true; } catch { firstOk = false; }
        assertTrue(firstOk); // reference and buggy both succeed on first call

        // Second initialization attempt on the same contract instance
        vm.prank(actualControl);
        bool secondOk;
        try c.initialize(actualControl) { secondOk = true; } catch { secondOk = false; }

        // The reference must revert (secondOk == false), the buggy accepts the second call (secondOk == true).
        // We assert that the second call fails (reference property). The fuzzer will find a case where buggy does not revert.
        assertTrue(!secondOk);
    }
}

contract AccessReturnTrueStub {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}

