pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address accessControl) public {
        vm.assume(accessControl != address(0));

        c.initialize(accessControl);

        // Try to call `setLimits`, which uses the `checkAccess` modifier.
        // `checkAccess` calls `_checkAccess`, which does NOT use `onlyInitializing`.
        // Instead, try `upgradeToAndCall` which goes through `_authorizeUpgrade`.
        // `_authorizeUpgrade` has `onlyProxy` modifier implicitly? No, it's `view` with `checkAccess`.
        // Actually, `_authorizeUpgrade` uses `checkAccess(bytes4(0))`, no `onlyInitializing`.
        // The difference: after `initialize` completes, the `_initializing` flag is false in M.
        // The test should check that `_isInitializing()` returns `false` after `initialize` completes
        // in both, but that the flag was set during the call.
        // Wait, the bug removes the line that sets `_initializing = true`, so `reinitializer`
        // and `onlyInitializing` will revert.
        // Call `upgradeToAndCall` -> `onlyProxy` -> no `onlyInitializing`.
        // The property: after initialize, calling any function with `onlyInitializing` modifier
        // should succeed. In the reference, it succeeds because the flag was set;
        // in the buggy, it fails because the flag was never set.
        // But `initialize` itself does not expose `onlyInitializing` after it finishes.
        // The bug makes `_isInitializing()` return false *during* `initialize`.
        // After `initialize`, `reinitializer` will fail in the buggy version.
        // So we can call a function that uses `reinitializer` or `onlyInitializing`.
        // `__Access_init` and `__UUPSUpgradeable_init` are internal and only called from `initialize`.
        // To hit `reinitializer` or `onlyInitializing` externally, we need an external function.
        // The contract does not have other initializers.
        // Actually, the buggy version's `initialize` will succeed, but the `_initializing` flag
        // is false. The `onlyInitializing` modifier is used in `__Access_init` and `__UUPSUpgradeable_init`.
        // But those are called during `initialize`, so they will revert in the buggy version!
        // Wait, the buggy modifier removed `$._initializing = true` inside `if (isTopLevelCall)`.
        // So `_isInitializing()` returns false during `initialize` in the buggy version.
        // Then `__Access_init` has `onlyInitializing`, which calls `_checkInitializing()` -> `_isInitializing()`.
        // In the reference, `_isInitializing()` returns true, so it passes.
        // In the buggy, `_isInitializing()` returns false, so it reverts with `NotInitializing`.
        // Therefore, `initialize` itself will revert in the buggy version!
        // So the property: `initialize` should succeed for any non-zero accessControl.
        // The reference succeeds, the buggy reverts.
        // Verify by checking if `initialize` reverts.
        bool ok = true;
        try c.initialize(accessControl) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

